// Format + write the generated fixture files (ES5, export default).
// The routes file re-exports the roads file, so the watch imports
// only fixture-real-map.js. Both files are generated; DO NOT EDIT.
import fs from 'node:fs';
import path from 'node:path';

const REGENERATE = 'node spikes/tools/real-map-fixture/build-real-map-fixture.js';

export function headerLines(today) {
  return [
    '// Generated by spikes/tools/real-map-fixture/build-real-map-fixture.js',
    '// \u00a9 OpenStreetMap contributors (ODbL).',
    '// Route: Valhalla (valhalla1.openstreetmap.de). Roads: Overpass API (overpass-api.de).',
    `// Created: ${today}. Regenerate: ${REGENERATE}`,
    '// DO NOT EDIT BY HAND.',
  ];
}

function formatDeltaArray(delta, indent, perLine = 12) {
  const lines = [];
  for (let i = 0; i < delta.length; i += perLine) {
    const chunk = delta.slice(i, i + perLine).join(', ');
    lines.push(indent + chunk + (i + perLine < delta.length ? ',' : ''));
  }
  return '[\n' + lines.join('\n') + '\n' + indent.slice(0, -4) + ']';
}

function formatRoute(key, route) {
  const out = [];
  out.push(`        ${key}: {`);
  out.push(`            routeDelta: ${formatDeltaArray(route.routeDelta, '                ')},`);
  out.push('            maneuvers: [');
  for (const m of route.maneuvers) {
    out.push(`                { distanceM: ${m.distanceM}, maneuver: '${m.maneuver}', streetName: ${JSON.stringify(m.streetName)} },`);
  }
  out.push('            ],');
  out.push(`            lengthM: ${route.lengthM}`);
  out.push('        }' + (key === 'motorbike' ? ',' : ''));
  return out.join('\n');
}

export function writeFixtureFiles(jsRoot, today, outRoutes, major, minor) {
  const mapLines = [
    ...headerLines(today),
    "import roads from './fixture-real-map-roads.js';",
    '',
    'export default {',
    '    routes: {',
    formatRoute('motorbike', outRoutes.motorbike),
    formatRoute('car', outRoutes.car),
    '    },',
    '    roadsMajorDelta: roads.roadsMajorDelta,',
    '    roadsMinorDelta: roads.roadsMinorDelta',
    '};',
    '',
  ];
  fs.writeFileSync(path.join(jsRoot, 'fixture-real-map.js'), mapLines.join('\n'));

  const roadLines = [
    ...headerLines(today),
    '',
    'export default {',
    '    roadsMajorDelta: [',
    ...major.map((d) => '        ' + JSON.stringify(d) + ','),
    '    ],',
    '    roadsMinorDelta: [',
    ...minor.map((d) => '        ' + JSON.stringify(d) + ','),
    '    ],',
    '};',
    '',
  ];
  fs.writeFileSync(path.join(jsRoot, 'fixture-real-map-roads.js'), roadLines.join('\n'));
}
